function editCalls(text) {
  if (text.includes("./camfx")) return { text, notes: [] };
  if (!text.includes("async startCamera()")) throw new Error("the camera in calls (run aura-call-camera-setup.cjs first)");
  let t = text;
  t = swapOnce(t, 'import { ringtone, soundPrefs } from "./sounds"; // your ringtone (Settings > Calls and messages)\n',
    'import { ringtone, soundPrefs } from "./sounds"; // your ringtone (Settings > Calls and messages)\n' +
    'import { cameraEffects } from "./camfx"; // your camera background in calls (' + MARK + ")\n",
    "the imports at the top of the calls file");
  t = swapOnce(t,
    "    if (mine !== session || !rtc || !state.call?.camStarting) return stopStream(stream); // the call ended (or you pressed again) meanwhile\n" +
    "    const track = stream.getVideoTracks()[0];\n" +
    "    try { await lane.sender.replaceTrack(track); }\n" +
    "    catch { stopStream(stream); patch({ camStarting: false }); return toast(\"Your camera couldn't be sent. Try again.\", \"err\"); }\n" +
    "    if (mine !== session || !rtc) return stopStream(stream);\n" +
    "    rtc.cam = stream;\n",
    "    if (mine !== session || !rtc || !state.call?.camStarting) return stopStream(stream); // the call ended (or you pressed again) meanwhile\n" +
    "    // What's sent has your background (Settings > Camera); the camera itself is kept to let go of later (" + MARK + ")\n" +
    "    const raw = stream;\n" +
    "    const fx = cameraEffects(raw);\n" +
    "    if (fx) stream = fx.stream;\n" +
    "    const track = stream.getVideoTracks()[0];\n" +
    "    try { await lane.sender.replaceTrack(track); }\n" +
    "    catch { stopStream(stream); stopStream(raw); patch({ camStarting: false }); return toast(\"Your camera couldn't be sent. Try again.\", \"err\"); }\n" +
    "    if (mine !== session || !rtc) { stopStream(raw); return stopStream(stream); }\n" +
    "    rtc.cam = stream; rtc.camRaw = raw;\n",
    "where your camera is sent in a call");
  t = swapOnce(t, "    track.onended = () => { if (rtc?.cam === stream) { callActions.stopCamera(); toast(\"Your camera was disconnected.\", \"err\"); } };\n",
    "    const camTrack = raw.getVideoTracks()[0];\n" +
    "    if (camTrack) camTrack.onended = () => { if (rtc?.camRaw === raw) { callActions.stopCamera(); toast(\"Your camera was disconnected.\", \"err\"); } };\n",
    "where an unplugged camera is noticed in a call");
  t = swapOnce(t, "    if (rtc?.cam) { stopStream(rtc.cam); rtc.cam = null; }\n",
    "    if (rtc?.cam) { stopStream(rtc.cam); rtc.cam = null; }\n    if (rtc?.camRaw) { stopStream(rtc.camRaw); rtc.camRaw = null; } // the camera itself\n",
    "where your camera turns off in a call");
  t = swapOnce(t, "  stopStream(r.cam); // and your camera (Added by aura-call-camera-setup.cjs)\n",
    "  stopStream(r.cam); // and your camera (Added by aura-call-camera-setup.cjs)\n  stopStream(r.camRaw); // (the camera itself: " + MARK + ")\n",
    "where a call is tidied up");
  return { text: t, notes: ["your background goes into calls too"] };
}

// The free MediaPipe package, pinned to a release from July 2026
function editPackage(text) {
  if (text.includes('"@mediapipe/tasks-vision"')) return { text, notes: [] };
  return {
    text: swapOnce(text, '  "dependencies": {\n', '  "dependencies": {\n    "@mediapipe/tasks-vision": "1.0.1",\n', 'the dependencies list ( "dependencies": { )'),
    notes: ["adds Google's free MediaPipe (1.0.1) for finding you in the picture"],
  };
}

// ── AURA's checks (only when they are installed) ─────────────────────────────
function editRunner(text) {
  if (/camera-backgrounds\.cjs/.test(text)) return { text, notes: [] };
  const lines = text.split("\n");
  let at = -1;
  for (let i = 0; i < lines.length; i++) if (/add\("window",/.test(lines[i])) at = i;
  if (at < 0) return { text, notes: ["(couldn't find where to add the check, so npm test doesn't include it)"] };
  lines.splice(at + 1, 0, 'if (fs.existsSync(path.join(__dirname, "camera-backgrounds.cjs"))) add("window", "Camera backgrounds and green screen", "camera-backgrounds.cjs");');
  return { text: lines.join("\n"), notes: ["npm test now checks camera backgrounds too"] };
}

// Does `node` accept the file? Catches a bad edit before anything is written.
function syntaxProblem(text) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "aura-check-"));
  const file = path.join(dir, "check.cjs");
  try {
    fs.writeFileSync(file, text);
    const r = spawnSync(process.execPath, ["--check", file], { encoding: "utf8" });
    return r.status === 0 ? "" : String(r.stderr || "syntax error").split("\n").filter(Boolean).slice(0, 4).join(" | ");
  } catch { return ""; } finally { try { fs.rmSync(dir, { recursive: true, force: true }); } catch {} }
}

// ── Undo ──────────────────────────────────────────────────────────────────────
function undo() {
  let restored = 0;
  const visit = (dir, depth = 0) => {
    if (depth > 7) return;
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if ((!SKIP_DIRS.has(entry.name) || entry.name === "tests") && !entry.name.startsWith(".")) visit(full, depth + 1);
      } else if (entry.name.endsWith(BAK)) {
        const target = full.slice(0, -BAK.length);
        fs.copyFileSync(full, target); fs.unlinkSync(full);
        say("  restored  " + rel(target)); restored++;
      } else if (entry.name === "camera-backgrounds.cjs" || entry.name === "camfx.js") {
        try {
          if (fs.readFileSync(full, "utf8").includes(MARK)) {
            fs.unlinkSync(full); say("  removed   " + rel(full)); restored++;
            const model = path.join(dir, "selfie_segmenter.tflite");
            if (entry.name === "camfx.js" && fs.existsSync(model)) { fs.unlinkSync(model); say("  removed   " + rel(model)); }
          }
        } catch {}
      }
    }
  };
  say();
  visit(ROOT);
  say(restored ? "Undo finished. Camera backgrounds are gone. Run  npm install  once to tidy up the packages." : "Nothing to undo.");
  say();
}

// ── Run ───────────────────────────────────────────────────────────────────────
function run() {
  const pkgFile = path.join(ROOT, "package.json");
  if (!fs.existsSync(pkgFile)) stop(["This isn't your AURA project folder (no package.json here).", "Move this file next to package.json and run it from there."]);
  if (UNDO) return undo();

  const need = "Make sure this file is in your AURA project folder, next to package.json.";
  let pkgMain = "";
  try { pkgMain = String(JSON.parse(fs.readFileSync(pkgFile, "utf8")).main || ""); } catch {}
  const startFile = pkgMain ? path.resolve(ROOT, pkgMain) : "";
  const comp = (h) => /[\\/]components[\\/]/.test(h.file);
  const files = {
    camera: findOne("your camera file", (t) => /export function CameraPanel\s*\(/.test(t) && /export function CameraSettings\s*\(/.test(t), need + " The camera update needs to be installed first (aura-camera-setup.cjs).", [
      (h) => /^camera\.[jt]sx?$/.test(path.basename(h.file)),
    ]),
  };

  const plan = [];
  const problems = [];
  const consider = (label, file, edit, checkSyntax) => {
    const { text, eol } = readText(file);
    try {
      const result = edit(text);
      if (checkSyntax && result.text !== text) { const bad = syntaxProblem(result.text); if (bad) throw new Error("a way to edit it safely (" + bad + ")"); }
      plan.push({ label, file, before: text, after: result.text, eol, notes: result.notes });
    } catch (e) { problems.push("In " + rel(file) + " I couldn't find " + e.message + "."); }
  };
  consider("camera file", files.camera, editCamera, false);
  const callsFile = path.join(path.dirname(files.camera), "calls.jsx");
  if (fs.existsSync(callsFile) && fs.readFileSync(callsFile, "utf8").includes("async startCamera()")) consider("calls file", callsFile, editCalls, false);
  consider("packages", pkgFile, editPackage, false);
  const lockFile = path.join(ROOT, "package-lock.json");
  const runner = path.join(ROOT, "tests", "run.cjs");
  const hasChecks = fs.existsSync(runner);
  if (hasChecks) consider("checks", runner, editRunner, true);

  const created = [{ label: "backgrounds", file: path.join(path.dirname(files.camera), "camfx.js"), content: FILES.camfx }];
  if (hasChecks) created.push({ label: "checks", file: path.join(ROOT, "tests", "camera-backgrounds.cjs"), content: FILES.test });
  const model = { label: "model", file: path.join(path.dirname(files.camera), "selfie_segmenter.tflite"), data: Buffer.from(FILES.model, "base64") };
  model.note = fs.existsSync(model.file) ? (Buffer.compare(fs.readFileSync(model.file), model.data) === 0 ? "already done" : "updated") : "created";
  for (const c of created) {
    c.note = "created";
    if (fs.existsSync(c.file)) {
      const existing = readText(c.file).text;
      if (!existing.includes(MARK)) problems.push(rel(c.file) + " already exists and wasn't made by this script, so I left it alone.");
      else c.note = existing === c.content ? "already done" : "updated";
    }
  }
  if (problems.length) stop([...problems, "Copy this message to Claude."]);

  say();
  say(DRY ? "Dry run. This is what would change:" : "AURA: camera backgrounds");
  say();
  for (const step of plan) {
    if (step.after !== step.before && !DRY) {
      const bak = step.file + BAK;
      if (!fs.existsSync(bak)) fs.copyFileSync(step.file, bak);
      fs.writeFileSync(step.file, withEol(step.after, step.eol));
    }
    say("  " + (step.label + ":").padEnd(13) + rel(step.file));
    (step.notes.length ? step.notes : ["already done"]).forEach((n) => say("               - " + n));
  }
  for (const c of created) {
    if (c.note !== "already done" && !DRY) { fs.mkdirSync(path.dirname(c.file), { recursive: true }); fs.writeFileSync(c.file, c.content); }
    say("  " + (c.label + ":").padEnd(13) + rel(c.file));
    say("               - " + c.note);
  }
  if (model.note !== "already done" && !DRY) fs.writeFileSync(model.file, model.data);
  say("  " + "model:".padEnd(13) + rel(model.file));
  say("               - " + model.note);
  say();
  if (DRY) { say("Run it again without --dry-run to apply."); say(); return; }
  // Add MediaPipe to node_modules (and package-lock.json) when it isn't there yet
  const installed = fs.existsSync(path.join(ROOT, "node_modules", "@mediapipe", "tasks-vision", "package.json"));
  const pkgStep = plan.find((p) => p.file === pkgFile);
  if (!installed || (pkgStep && pkgStep.after !== pkgStep.before)) {
    if (fs.existsSync(lockFile) && !fs.existsSync(lockFile + BAK)) fs.copyFileSync(lockFile, lockFile + BAK);
    say("Running  npm install  to add MediaPipe (this can take a minute)...");
    const r = spawnSync(process.platform === "win32" ? "npm.cmd" : "npm", ["install"], { cwd: ROOT, stdio: "inherit", shell: process.platform === "win32" });
    say();
    if (r.status !== 0) { say("npm install didn't finish. Check your internet connection, then run  npm install  yourself."); say(); }
  }
  say("Done. Restart AURA (stop it in the terminal and start it again), then pick a background in Settings > Camera.");
  if (hasChecks) say("Run  npm test  before your next release.");
  say("To undo later:  node aura-camera-backgrounds-setup.cjs --undo");
  say();
}

try { run(); } catch (e) { stop(["Something unexpected went wrong: " + e.message, "Copy this message to Claude."]); }
